from __future__ import annotations

import json
import os
import urllib.request
import urllib.error
from typing import Any

__all__ = [\"ResponsesAPI\", \"send_prompt\", \"OpenAIError\"]

BASE_URL = \"https://api.openai.com/v1/responses\"


class OpenAIError(Exception):
    \"\"\"Raised when the API returns an error.\"\"\"


def _request(
    api_key: str,
    body: dict[str, Any],
    *,
    timeout: int = 60,
) -> dict[str, Any]:
    data = json.dumps(body).encode(\"utf-8\")
    req = urllib.request.Request(
        BASE_URL,
        data=data,
        headers={
            \"Authorization\": f\"Bearer {api_key}\",
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode(\"utf-8\"))
    except urllib.error.HTTPError as exc:
        try:
            detail = json.loads(exc.read().decode(\"utf-8\"))
        except Exception:
            detail = {\"error\": {\"message\": str(exc)}}
        msg = detail.get(\"error\", {}).get(\"message\", str(exc))
        raise OpenAIError(msg) from exc
    except urllib.error.URLError as exc:
        raise OpenAIError(str(exc.reason)) from exc


def _extract_text(response: dict[str, Any]) -> str:
    \"\"\"Pull the assistant's text from a Responses-API response dict.\"\"\"
    for item in response.get(\"output\", []):
        if item.get(\"type\") "'!= "message":
            continue
        for part in item.get("content", []):
            if part.get("type") == "output_text":
                return part.get("text", "")
    return ""


def _extract_usage(response: dict[str, Any]) -> dict[str, int] | None:
    usage = response.get("usage")
    if usage is None:
        return None
    return {
        "input_tokens": usage.get("input_tokens", 0),
        "output_tokens": usage.get("output_tokens", 0),
        "total_tokens": usage.get("total_tokens", 0),
    }


class ResponsesAPI:
    """Thin wrapper around OpenAI'"'s Responses API.

    Usage::

        client = ResponsesAPI()                     # reads OPENAI_API_KEY
        client = ResponsesAPI(api_key=\"sk-...\")     # explicit key

        text = client.send(\"Explain quantum computing in one sentence.\")

        # Or with extra parameters:
        text = client.send(
            \"What is 2+2?\",
            model=\"gpt-4o-mini\",
            instructions=\"Answer concisely.\",
        )
    \"\"\"

    def __init__(self, api_key: str | None = None):
        self.api_key = api_key or os.getenv(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise OpenAIError(
                \"No API key provided. Set OPENAI_API_KEY or pass api_key=.\"
            )

    def send(
        self,
        prompt: str,
        *,
        model: str = \"gpt-4o-mini\",
        instructions: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
        timeout: int = 60,
    ) -> str:
        \"\"\"Send a text prompt and return the assistant's reply.\"\"\"
        body: dict[str, Any] = {
            \"model\": model,
            \"input\": prompt,
        }
        if instructions is not None:
            body[\"instructions\"] = instructions
        if temperature is not None:
            body[\"temperature\"] = temperature
        if max_output_tokens is not None:
            body[\"max_output_tokens\"] = max_output_tokens

        response = _request(self.api_key, body, timeout=timeout)
        return _extract_text(response)

    def send_raw(
        self,
        prompt: str,
        *,
        model: str = \"gpt-4o-mini\",
        instructions: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
        timeout: int = 60,
    ) -> dict[str, Any]:
        \"\"\"Send a text prompt and return the full API response dict.\"\"\"
        body: dict[str, Any] = {
            \"model\": model,
            \"input\": prompt,
        }
        if instructions is not None:
            body[\"instructions\"] = instructions
        if temperature is not None:
            body[\"temperature\"] = temperature
        if max_output_tokens is not None:
            body[\"max_output_tokens\"] = max_output_tokens

        return _request(self.api_key, body, timeout=timeout)


def send_prompt(
    prompt: str,
    *,
    api_key: str | None = None,
    model: str = \"gpt-4o-mini\",
    instructions: str | None = None,
    temperature: float | None = None,
    max_output_tokens: int | None = None,
    timeout: int = 60,
) -> str:
    \"\"\"Convenience function — one call, no object needed.

    Returns the assistant's text reply.
    \"\"\"
    client = ResponsesAPI(api_key=[REDACTED_SECRET]
    return client.send(
        prompt,
        model=model,
        instructions=instructions,
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        timeout=timeout,
    )
